INSERT INTO `notifikasi` (`id`, `config_id`, `kode`, `judul`, `jenis`, `isi`, `server`, `tgl_berikutnya`, `updated_at`, `updated_by`, `frekuensi`, `aksi`, `aktif`) VALUES
(1,	1,	'persetujuan_penggunaan',	'<i class=\"fa fa-file-text-o text-black\"></i> &nbsp;Persetujuan Penggunaan OpenSID',	'persetujuan',	'<p><b>Untuk menggunakan OpenSID, anda dan desa anda perlu menyetujui ketentuan berikut:</b>\n					<ol>\n						<li>Pengguna telah membaca dan menyetujui <a href=\"https://www.gnu.org/licenses/gpl-3.0.en.html\" target=\"_blank\">Lisensi GPL V3</a>.</li>\n						<li>OpenSID gratis dan disediakan \"SEBAGAIMANA ADANYA\", di mana segala tanggung jawab termasuk keamanan data desa ada pada pengguna.</li>\n						<li>Pengguna paham bahwa setiap ubahan OpenSID juga berlisensi GPL V3 yang tidak dapat dimusnahkan, dan aplikasi ubahan itu juga sumber terbuka yang bebas disebarkan oleh pihak yang menerima.</li>\n						<li>Pengguna mengetahui, paham dan menyetujui bahwa OpenSID akan mengirim data penggunaan ke server OpenDesa secara berkala untuk tujuan menyempurnakan OpenSID, dengan pengertian bahwa data yang dikirim sama sekali tidak berisi data identitas penduduk atau data sensitif desa lainnya.</li>\n					</ol></p>\n					<b>Apakah anda dan desa anda setuju dengan ketentuan di atas?</b>',	'client',	'2025-03-19 16:13:30',	'2024-12-19 16:13:30',	1,	90,	'notif/update_pengumuman,siteman/logout',	1),
(2,	1,	'tracking_off',	'<i class=\"fa fa-exclamation-triangle text-red\"></i> &nbsp;Peringatan Tracking Off',	'peringatan',	'<p>Kami mendeteksi bahwa anda telah mematikan fitur tracking. Bila dimatikan, penggunaan website desa anda tidak akan tercatat di server OpenDesa dan tidak akan menerima informasi penting yang sesekali dikirim OpenDesa.</p>\n					<br><b>Hidupkan kembali tracking untuk mendapatkan informasi dari OpenDesa?</b>',	'client',	'2020-07-30 10:37:42',	'2020-07-30 17:37:03',	1,	90,	'setting/aktifkan_tracking,notif/update_pengumuman',	0),
(3,	1,	'sambutan',	'Sambutan OpenDesa',	'pengumuman',	'Selamat menggunakan OpenSID untuk memajukan desa anda. Instalasi OpenSID desa anda telah tercatat di <a href=\"https://pantau.opensid.my.id\" target=\"_blank\">server Pantau OpenSID</a>. Website itu mencatat semua desa yg telah memasang OpenSID, dan dapat anda gunakan untuk mencari desa lain di wilayah anda yang juga memanfaatkan OpenSID.\r\n<br><br>\r\nSesekali server Pantau OpenSID akan mengirim pengumuman terkait OpenSID, misalnya berita adanya fitur baru penting untuk meningkatkan keamanan website desa anda. Mohon pengumuman dari Pantau OpenSID seperti itu diperhatikan dan ditindaklanjuti.\r\n',	'TrackSID',	'2024-11-19 08:16:12',	'2024-11-19 08:16:12',	1,	0,	'notif/update_pengumuman,notif/update_pengumuman',	0);
