INSERT INTO `surat_dinas` (`id`, `config_id`, `nama`, `url_surat`, `kode_surat`, `lampiran`, `kunci`, `favorit`, `jenis`, `masa_berlaku`, `satuan_masa_berlaku`, `qr_code`, `logo_garuda`, `template`, `template_desa`, `form_isian`, `kode_isian`, `orientasi`, `ukuran`, `margin`, `margin_global`, `footer`, `header`, `format_nomor`, `format_nomor_global`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES
(1,	1,	'Pernyataan',	'sistem-surat-pernyataan',	'S1',	NULL,	0,	0,	3,	0,	'd',	0,	0,	'<h4 style=\"margin: 0; text-align: center;\"><span style=\"text-decoration: underline;\">[JUdul_surat]</span></h4>\r\n<p style=\"margin: 0; text-align: center;\">Nomor : [Format_nomor_suraT]<br><br></p>\r\n<p style=\"text-align: justify; text-indent: 30px;\">Yang bertanda tangan di bawah ini : </p>\r\n<table style=\"border-collapse: collapse; width: 100.002%; height: 77.7917px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 26.5278px;\">\r\n<td style=\"width: 7.66792%; text-align: center; height: 26.5278px; vertical-align: top;\"> </td>\r\n<td style=\"height: 26.5278px;\">Nama</td>\r\n<td style=\"width: 3.90584%; text-align: center; height: 26.5278px; vertical-align: top;\">:</td>\r\n<td style=\"width: 70.3051%; height: 26.5278px; text-align: justify; vertical-align: top;\">[Form_namA]</td>\r\n</tr>\r\n<tr style=\"height: 23.4954px;\">\r\n<td style=\"width: 7.66792%; text-align: center; height: 23.4954px; vertical-align: top;\"> </td>\r\n<td style=\"width: 18.0817%; text-align: left; height: 23.4954px; vertical-align: top;\">Jabatan</td>\r\n<td style=\"width: 3.90584%; text-align: center; height: 23.4954px; vertical-align: top;\">:</td>\r\n<td style=\"width: 70.3051%; height: 23.4954px; text-align: justify; vertical-align: top;\">[Form_jabataN]</td>\r\n</tr>\r\n<tr style=\"height: 27.7685px;\">\r\n<td style=\"width: 7.66792%; text-align: center; height: 27.7685px; vertical-align: top;\"> </td>\r\n<td style=\"width: 18.0817%; text-align: left; height: 27.7685px; vertical-align: top;\">Alamat<br><br></td>\r\n<td style=\"width: 3.90584%; text-align: center; height: 27.7685px; vertical-align: top;\">:<br><br></td>\r\n<td style=\"width: 70.3051%; height: 27.7685px; text-align: justify; vertical-align: top;\">[Form_alamaT]</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"text-align: justify; text-indent: 30px;\">Dalam hal ini bertindak untuk dan atas nama diri sendiri serta  Aparatur [Sebutan_desa] [NaMa_desa], menyatakan bahwa tidak ada Aparatur [Sebutan_desa] [NaMa_desa] yang terjerat tindak pidana Korupsi. Kolusi, dan Nepotisme (KKN) terhitung 3 (tiga) tahun terakhir hingga tanggal dibuatnya surat pernyataan ini.</p>\r\n<p style=\"text-align: justify; text-indent: 30px;\">Demikian surat pernyataan ini dibuat dengan sebenar-benarnya untuk dapat dipergunakan sebagaimana mestinya. Demikian surat pernyataan ini dibuat dengan sebenar-benarnya untuk dapat dipergunakan sebagaimana mestinya.<br><br></p>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%; text-align: center;\">[NaMa_desa], [TgL_surat]</td>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%; text-align: center;\">[Atas_namA]</td>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%;\"><br><br><br><br></td>\r\n<td style=\"width: 35%;\"> </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%; text-align: center;\">[Nama_pamonG]</td>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%; text-align: center;\">[Sebutan_nip_desA] : [Nip_pamonG]</td>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<br>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n<td style=\"width: 30%; text-align: center;\">Mengetahui :<br><br></td>\r\n<td style=\"width: 35%; text-align: center;\"> </td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 35%; text-align: center;\